97	/**
98	 * Adds custom redirect logic to redirect after an item is deleted
99	 * 1. Do not navigate if the deleted item is not selected
100	 * 2. If it was the only item, navigate to a creation url
101	 * 3. If there are other items, navigate to an item close to the current one
102	 * **/
103	
104	enum RedirectAction {
105	  NA = "NA", // No action is needed
106	  CREATE = "CREATE", // Navigate to a creation URL
107	  ITEM = "ITEM", // Navigate to this item
108	}
109	interface RedirectActionDescription {
110	  action: RedirectAction;
111	  payload?: EntityItem;
112	}
113	
114	function getNextEntityAfterDelete(
115	  deletedId: string,
116	  allItems: EntityItem[],
117	): RedirectActionDescription {
118	  const currentSelectedEntity = identifyEntityFromPath(
119	    window.location.pathname,
120	  );
121	  const isSelectedActionDeleted = currentSelectedEntity.id === deletedId;
122	
123	  // If deleted item is not currently selected, don't redirect
124	  if (!isSelectedActionDeleted) {
125	    return {
126	      action: RedirectAction.NA,
127	    };
128	  }
129	
130	  const otherItems = allItems.filter((a) => deletedId !== a.key);
131	  // If no other action is remaining, navigate to the creation url
132	  if (otherItems.length === 0) {
133	    return {
134	      action: RedirectAction.CREATE,
135	    };
136	  }
137	
138	  // Check if another action is present in the group and redirect to it, or else
139	  // navigate to tht top of the list
140	  const currentSortedList: EditorSegmentList =
141	    groupAndSortEntitySegmentList(allItems);
142	
143	  let remainingGroupEntities: EntityItem[] = [];
144	  for (const { items } of currentSortedList) {
145	    if (items.find((a) => a.key === deletedId)) {
146	      remainingGroupEntities = items.filter((a) => a.key !== deletedId);
147	      break;
148	    }
149	  }
150	
151	  if (remainingGroupEntities.length === 0) {
152	    return {
153	      action: RedirectAction.ITEM,
154	      payload: otherItems[0],
155	    };
156	  } else {
157	    return {
158	      action: RedirectAction.ITEM,
159	      payload: remainingGroupEntities[0],
160	    };
161	  }
162	}
163	
164	function* storeIDEViewChangeSaga(
165	  action: ReduxAction<{ view: EditorViewMode }>,
166	) {
167	  yield call(storeIDEViewMode, action.payload.view);
168	}
169	
170	function* restoreIDEViewModeSaga() {
171	  const storedState: EditorViewMode = yield call(retrieveIDEViewMode);
172	  if (storedState) {
173	    yield put(setIdeEditorViewMode(storedState));
174	  }
175	}
176	
177	export default function* root() {
178	  yield all([
179	    takeEvery(
180	      ReduxActionTypes.SET_IDE_EDITOR_VIEW_MODE,
181	      storeIDEViewChangeSaga,
182	    ),
183	    takeEvery(
184	      ReduxActionTypes.RESTORE_IDE_EDITOR_VIEW_MODE,
185	      restoreIDEViewModeSaga,
186	    ),
187	  ]);
188	}
